			function initSelect() {
			    
			    var cmbBizYr = app.lookup("cmb1");
			    if (cmbBizYr.isSelected(0) && cmbBizYr.getItemByValue(moment().year())) cmbBizYr.selectItemByValue(moment().year());
			    app.lookup("cmnDaterangePicker1").startDate = moment().subtract(1, 'months').format('YYYYMMDD');
			    app.lookup("cmnDaterangePicker1").endDate = moment().format('YYYYMMDD');
			    if (app.lookup("cmb2").getItemCount() == 2) app.lookup("cmb2").selectItem(1);
			    app.lookup("cmb4").clearFilter();
			    app.lookup("cmb4").selectItem(0);
			}

			function setAprvSttsCmb(psType) {
			    var cmb4 = app.lookup("cmb4");
			    var btn1 = app.lookup("btn1");
			    var aprvSttsSeCd = cmb4.value;
			    
			    cmb4.readOnly = true;
			    btn1.visible = false;
			    switch (aprvSttsSeCd) {
			        case '0':
			            if (modifyAuth) {
			                cmb4.readOnly = false;
			                cmb4.setFilter("value == '0' || value == '1'");
			                if (psType == "READ")
			                    btn1.visible = true;
			            }
			            break;
			        case '1':
			        case '4':
			            if (aprvAuth) {
			                cmb4.readOnly = false;
			                cmb4.setFilter("value != '0' && value != '1'");
			                btn1.visible = true;
			            }
			            break;
			        case '5':
			            if (modifyAuth) {
			                cmb4.readOnly = false;
			                cmb4.setFilter("value == '5' || value == '1'");
			                if (psType == "READ")
			                    btn1.visible = true;
			            }
			            break;
			    }
			}

